'use strict';
const app=document.querySelector('#app'),$=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),shuffle=a=>[...a].sort(()=>0).map(x=>[Math.random(),x]).sort((a,b)=>a[0]-b[0]).map(x=>x[1]);
let st={c:1,d:1,xp:0,miss:{},done:{}},q=[],i=0,score=0,mode='',locked=false,review=false;try{Object.assign(st,JSON.parse(localStorage.wortreise||'{}'))}catch{}
function save(){try{localStorage.wortreise=JSON.stringify(st)}catch{}$('#points').textContent='★ '+st.xp+' نقطة'}
let all=DAYS.flatMap(d=>[...d.cards.map(([de,ar],i)=>({id:d.d+'s'+i,de,ar,k:'s',d:d.d})),...d.n.map(([de,ar],i)=>({id:d.d+'n'+i,de,ar,k:'n',d:d.d}))]);
function home(){save();let c=st.c,days=DAYS.filter(d=>d.c==c),n=Object.keys(st.miss).length;
app.innerHTML='<section class="hero cover"><span class=cap>أطلس الألمانية · A1+</span><h1>رحلة الكلمات</h1><p>كل نهار محطة، وكل جملة خطوة.</p></section><section class=card><span class=eyebrow>REISEPLAN</span><h2>المحطة ديالك</h2><div class=fields><label>الفصل<select id=chap>'+DAYS.filter(d=>d.d%5===1).map(d=>'<option value='+d.c+' '+(c===d.c?'selected':'')+'>'+d.c+' · '+esc(d.title)+'</option>').join('')+'</select></label><label>المحطة<select id=day>'+[...days.map(d=>[d.d,d.topic]),[c*5,'مراجعة الفصل']].map(([v,t])=>'<option value='+v+' '+(st.d===v?'selected':'')+'>نهار '+v+' · '+esc(t)+'</option>').join('')+'</select></label></div><p class=tag>جولات كمّلتي هنا: '+Object.keys(st.done).filter(k=>k.startsWith(st.d+'-')).length+' / 3</p></section><section class=card><span class=eyebrow>TRAINING</span><h2>اختار التحدّي</h2><button class=mode onclick="start(0)"><i>◎</i><span>اختار المعنى<small>قرا الجملة ولقا المعنى بالدارجة</small></span><span>‹</span></button><button class=mode onclick="start(1)"><i>✎</i><span>كتب من الذاكرة<small>من الدارجة للألمانية، بلا ما تشوف</small></span><span>‹</span></button><button class=mode onclick="start(2)"><i>Aa</i><span>تحدّي الأدوات<small dir=ltr>der · die · das</small></span><span>‹</span></button></section><button class=soft '+(!n?'disabled':'')+' onclick="start(3)">↻ راجع الأخطاء ديالك ('+n+')</button>';
$('#chap').onchange=e=>{st.c=+e.target.value;st.d=st.c*5-4;home()};$('#day').onchange=e=>{st.d=+e.target.value;home()}}
function start(m){mode=m;review=m===3;let pool=all.filter(o=>review?st.miss[o.id]:(st.d%5?o.d===st.d:Math.ceil(o.d/5)===st.c)&&o.k===(m===2?'n':'s'));q=shuffle(pool).slice(0,review||st.d%5===0?10:7);i=score=0;if(q.length)draw()}
function norm(s){return s.toLowerCase().normalize('NFC').replace(/[.,:;!?„“”"–—…]/g,' ').replace(/\s+/g,' ').trim()}
function draw(){locked=false;const o=q[i],m=review?(o.k==='n'?2:1):mode;
app.innerHTML='<section class=hero><span class=cap>'+ (review?'دفتر الأخطاء':'محطة '+st.d)+'</span><h2>'+['اختار المعنى','رجّع الجملة من الذاكرة','اختار الأداة'][m]+'</h2><span>'+(i+1)+' / '+q.length+'</span><div class=rail><i style="width:'+i/q.length*100+'%"></i></div></section><section class=card><div class=prompt dir=auto>'+esc(m===0?o.de:m===1?o.ar:o.de.replace(/^\S+ /,''))+'</div>'+(m===2?'<p style="text-align:center">'+esc(o.ar)+'</p>':'')+'<div id=choices></div><div id=feedback aria-live=polite></div></section><button class=soft onclick="home()">رجع للخريطة</button>';
let dest=$('#choices'),answer=m===2?o.de.split(' ')[0]:m===0?o.ar:o.de;
function check(v,b){if(locked)return;document.activeElement?.blur?.();locked=true;let ok=norm(v)===norm(answer);if(ok){score++;st.xp+=10;delete st.miss[o.id]}else st.miss[o.id]=true;save();dest.querySelectorAll('button,input').forEach(x=>x.disabled=true);if(b)b.className=ok?'right':'wrong';$('#feedback').innerHTML=(ok?'✓ بالصح!':'راجع البطاقة وعاود قولها:')+'<p dir=ltr>'+esc(o.de)+'</p><p>'+esc(o.ar)+'</p><button id=listen>🔊 سمع الألمانية</button><button class=gold id=next>'+(i+1===q.length?'شوف النتيجة':'كمّل')+'</button>';$('#listen').onclick=()=>{if(!window.speechSynthesis){$('#listen').textContent='النطق ما متوفرش فهاد المتصفح';return}let u=new SpeechSynthesisUtterance(o.de);u.lang='de-DE';u.rate=.85;speechSynthesis.cancel();speechSynthesis.speak(u)};$('#next').onclick=()=>{if(++i<q.length)draw();else end()}}
if(m===1){dest.innerHTML='<input aria-label="الجواب بالألمانية" dir=ltr enterkeyhint=done autocapitalize=sentences autocomplete=off placeholder="Auf Deutsch …"><button class=gold>صحّح</button><button class=soft>ما تذكرتش</button>';let inp=dest.firstChild;dest.children[1].onclick=()=>{if(inp.value.trim())check(inp.value)};dest.children[2].onclick=()=>check('');inp.onkeydown=e=>{if(e.key==='Enter'&&inp.value.trim())check(inp.value)}}else{let opts=m===2?['der','die','das']:shuffle([answer,...shuffle([...new Set(all.filter(x=>x.k==='s'&&x.ar!==answer&&x.de!==o.de).map(x=>x.ar))]).slice(0,2)]);opts.forEach(v=>{let b=document.createElement('button');b.textContent=v;b.onclick=()=>check(v,b);dest.appendChild(b)})}}
function end(){if(!review)st.done[st.d+'-'+mode]=true;save();app.innerHTML='<section class=hero><span class=cap>✦ نهاية الجولة</span><h1>'+score+' / '+q.length+'</h1><p>'+(score===q.length?'جبتيهم كاملين! جرّب تقول شي جملة بلا ما تشوف.':'الجمل اللي تعثرتي فيهم تلقاهم فمراجعة الأخطاء.')+'</p></section><button class=gold onclick="home()">رجع للخريطة</button>'}home()
